clc; clear;

figureDir = "figures";
if ~isfolder(figureDir)
    mkdir(figureDir);
end

opsMAT = OpenSeesMatlab;
ops = opsMAT.opensees;
opsvis = opsMAT.vis;
%%
%[text] 
params = struct();
params.NStory = 6;
params.NBay = 3;
params.NBayZ = 2;
params.dataDir = "Data";

params.runDynamic = false;
params.GMdir = "../GMfiles";
params.GMfiles = ["H-E01140", "H-E12140"];
params.GMdirections = [1, 2];
params.GMfactors = [1.5, 0.75];


results = genericFrame3DRCsec(opsMAT, params); %[output:4d90547a]
%%
%[text] 
%[text] 
% -------------------------------------------------------------------------
% Plot model with one large 3D view and three compact orthographic views
% -------------------------------------------------------------------------

% -------------------------------------------------------------------------
% Plot model with one large 3D view and three orthographic views
% -------------------------------------------------------------------------

figure("Color", "w", "Position", [100, 100, 1300, 800]); %[output:8ed2cb29]

fontName = "Times New Roman";
fontSizeMain = 18;
fontSizeSmall = 16;

% Axes positions: [left bottom width height]
% Larger spacing between subplots
posIso = [0.005, 0.045, 0.595, 0.9];

posXY  = [0.60, 0.690, 0.39, 0.2];
posXZ  = [0.60, 0.390, 0.39, 0.2];
posYZ  = [0.60, 0.090, 0.39, 0.2];

viewInfo = {
    "iso", "3D View",       posIso, -37.5, 30
    "xy",  "XY Plan View",  posXY,   0,    90
    "xz",  "XZ Elevation",  posXZ,   0,    0
    "yz",  "YZ Elevation",  posYZ,   90,   0
};

for i = 1:size(viewInfo, 1) %[output:group:7ffa0462]

    ax = axes("Position", viewInfo{i, 3}); %[output:8ed2cb29]
    opsMAT.vis.plotModel(ax=ax); %[output:0b3c6bbc] %[output:8ed2cb29]

    view(ax, viewInfo{i, 4}, viewInfo{i, 5});

    axis(ax, "equal");
    axis(ax, "tight");
    grid(ax, "on");
    box(ax, "on");

    title(ax, viewInfo{i, 2}, ...
        "FontName", fontName, ...
        "FontSize", fontSizeMain, ...
        "FontWeight", "normal");

    xlabel(ax, "X", "FontName", fontName);
    ylabel(ax, "Y", "FontName", fontName);
    zlabel(ax, "Z", "FontName", fontName);

    set(ax, ...
        "FontName", fontName, ...
        "FontSize", fontSizeSmall, ...
        "LineWidth", 1.0, ...
        "TickDir", "in");

    if viewInfo{i, 1} == "iso"
        set(ax, "FontSize", fontSizeMain);
    else
        set(ax, "FontSize", fontSizeMain);
        xlabel(ax, "", "FontName", fontName);
        ylabel(ax, "", "FontName", fontName);
        zlabel(ax, "", "FontName", fontName);
    end
end %[output:group:7ffa0462]
exportgraphics(gcf, fullfile(figureDir, "Frame3D_Model.pdf"), ... %[output:group:29bf4af3] %[output:741502b1] %[output:8ed2cb29]
    "ContentType","vector"); %[output:group:29bf4af3] %[output:741502b1] %[output:8ed2cb29]

nodeTags = double(ops.getNodeTags());
nodeTags = nodeTags(:);
nodeCoordinates = zeros(numel(nodeTags), 3);
for i = 1:numel(nodeTags)
    nodeCoordinates(i, :) = double(ops.nodeCoord(nodeTags(i)));
end
modelData = table(nodeTags, nodeCoordinates(:, 1), ...
    nodeCoordinates(:, 2), nodeCoordinates(:, 3), ...
    'VariableNames', {'NodeTag','X','Y','Z'});
writetable(modelData, fullfile(figureDir, "Frame3D_Model.csv"));
%[text] 
opsvis.polyscope.plotModel();
%%
%[text] 
%[text] 
tag = 1;
opsMAT.post.saveEigenData(tag, 10); %[output:1f5b187c]
eigenData = opsMAT.post.getEigenData(odbTag=tag);

opts.color.useColormap = true;

modeTags = [1, 2, 3, 4, 5, 6];
cmps = {"parula", "turbo", "jet", "cool", "winter", "spring"};

fig = figure( ... %[output:84f0caa0]
    "Color", "w", ... %[output:84f0caa0]
    "Position", [100, 100, 1200, 750]); %[output:84f0caa0]

t = tiledlayout(2, 3, ... %[output:84f0caa0]
    "TileSpacing", "compact", ... %[output:84f0caa0]
    "Padding", "compact"); %[output:84f0caa0]

for i = 1:6
    ax = nexttile(t); %[output:84f0caa0]

    opsMAT.vis.plotEigen( ...
        modeTags(i), ...
        eigenData, ...
        opts=opts, ...
        ax=ax);

    colormap(ax, cmps{i});

    axis(ax, "equal");
    axis(ax, "tight");
    axis(ax, "off");

    daspect(ax, [1, 1, 1]);

    camzoom(ax, 1.05);
end

% exportgraphics( ...
%     fig, ...
%     "figures/Frame3D_Eigen.png", ...
%     "Resolution", 300);
exportgraphics( ... %[output:group:5b53324d] %[output:84302513] %[output:84f0caa0]
    fig, ... %[output:84302513] %[output:84f0caa0]
    fullfile(figureDir, "Frame3D_Eigen.pdf"), ... %[output:84302513] %[output:84f0caa0]
    "ContentType","vector"); %[output:group:5b53324d] %[output:84302513] %[output:84f0caa0]

modeData = table();
for modeTag = modeTags
    modeShape = zeros(numel(nodeTags), 3);
    for i = 1:numel(nodeTags)
        eigenvector = double(ops.nodeEigenvector(nodeTags(i), modeTag));
        modeShape(i, :) = eigenvector(1:3);
    end
    modeData = [modeData; table( ...
        repmat(modeTag, numel(nodeTags), 1), nodeTags, ...
        nodeCoordinates(:, 1), nodeCoordinates(:, 2), nodeCoordinates(:, 3), ...
        modeShape(:, 1), modeShape(:, 2), modeShape(:, 3), ...
        'VariableNames', {'Mode','NodeTag','X','Y','Z','UX','UY','UZ'})]; %#ok<AGROW>
end
writetable(modeData, fullfile(figureDir, "Frame3D_Eigen.csv"));
